ValidationRule.errorConditionFormula:
AND(
    NOT(ISBLANK(TEXT(Slot__c))),
    OR(
        HOUR(TIMEVALUE(
            LPAD(TEXT(MOD(VALUE(LEFT(TEXT(Slot__c), 2)), 12) + IF(RIGHT(TEXT(Slot__c), 2) = "PM", 12, 0)), 2, "0")
            & ":" & MID(TEXT(Slot__c), 4, 2) & ":00.000"
        )) < 8,
        HOUR(TIMEVALUE(
            LPAD(TEXT(MOD(VALUE(LEFT(TEXT(Slot__c), 2)), 12) + IF(RIGHT(TEXT(Slot__c), 2) = "PM", 12, 0)), 2, "0")
            & ":" & MID(TEXT(Slot__c), 4, 2) & ":00.000"
        )) > 20
    )
)
